# Untrapped Ultra Mode - hardened self-repair engine
# Restores the original self-update/self-repair capability while adding safe validation,
# byte-for-byte verification, extension discovery, backups, retries and post-repair checks.
# Scope: Untrapped-owned files/processes only. Never changes Windows Firewall/WFP/DNS/routes/
# Hosts/proxy/adapters/VPN/override policy.
$ErrorActionPreference='Stop'
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path
$ExtensionRoot=Split-Path -Parent $Root
$RepoBase='https://raw.githubusercontent.com/mehdishah5372-hue/Untrapped/main/'
$BackupRoot=Join-Path $Root 'repair-backups'
$RepairReport=Join-Path $Root 'repair-success-latest.txt'
$stamp=Get-Date -Format 'yyyyMMdd-HHmmss'
$log=New-Object 'System.Collections.Generic.List[string]'
$changed=$false
$failed=$false
$attempts=2
function Log([string]$s){$x='['+(Get-Date -Format 'HH:mm:ss')+'] '+$s;Write-Host $x;[void]$log.Add($x)}
function Hash([byte[]]$b){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
function Valid([hashtable]$x,[byte[]]$b){try{$t=[Text.Encoding]::UTF8.GetString($b);if($b.Length -lt 20){throw 'File is unexpectedly small.'};switch($x.Type){'script'{[void][scriptblock]::Create($t)}'json'{$null=$t|ConvertFrom-Json}''js'{if($t -notmatch '(?s).{20,}'){throw 'JavaScript file is unexpectedly small.'}}'text'{}};return $true}catch{return $false}}
function Download([hashtable]$x){$url=$RepoBase+$x.Remote+'?cb='+[DateTime]::UtcNow.Ticks;Log ('DOWNLOAD START '+$x.Remote);$r=Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop;$b=[Text.Encoding]::UTF8.GetBytes([string]$r.Content);if(-not(Valid $x $b)){throw ('Canonical validation failed: '+$x.Remote)};Log ('DOWNLOAD OK '+$x.Remote+' ('+$b.Length+' bytes)');return $b}
function RepairOne([string]$base,[hashtable]$x,[string]$label){$path=Join-Path $base $x.Rel;Log ('CHECK '+$label+'/'+$x.Rel);$remote=$null;for($i=1;$i -le $attempts;$i++){try{$remote=Download $x;break}catch{Log ('DOWNLOAD RETRY '+$x.Remote+' attempt '+$i+': '+$_.Exception.Message);Start-Sleep -Milliseconds 500}};if($null -eq $remote){Log ('FAIL '+$label+'/'+$x.Rel+' canonical source unavailable/invalid.');$script:failed=$true;return};$same=$false;if(Test-Path -LiteralPath $path){try{$same=(Hash ([IO.File]::ReadAllBytes($path))) -eq (Hash $remote)}catch{}};if($same){Log ('OK CURRENT '+$label+'/'+$x.Rel);return};Log ('DIFF '+$label+'/'+$x.Rel);try{if(-not(Test-Path -LiteralPath $BackupRoot)){New-Item -ItemType Directory -Path $BackupRoot -Force|Out-Null};if(Test-Path -LiteralPath $path){$backup=Join-Path $BackupRoot ($stamp+'-'+$label.Replace('/','_')+'-'+$x.Rel.Replace('/','_'));Copy-Item -LiteralPath $path -Destination $backup -Force;Log ('BACKUP OK '+$backup)};$tmp=$path+'.repair-'+[guid]::NewGuid().ToString('N')+'.tmp';[IO.File]::WriteAllBytes($tmp,$remote);$written=[IO.File]::ReadAllBytes($tmp);if((Hash $written) -ne (Hash $remote)){throw 'Temporary SHA256 verification failed.'};if(-not(Valid $x $written)){throw 'Temporary content validation failed.'};Move-Item -LiteralPath $tmp -Destination $path -Force;$final=[IO.File]::ReadAllBytes($path);if((Hash $final) -ne (Hash $remote)){throw 'Post-write SHA256 verification failed.'};if(-not(Valid $x $final)){throw 'Post-write content validation failed.'};Log ('REPAIRED+VERIFIED '+$label+'/'+$x.Rel);$script:changed=$true}catch{Log ('FAIL '+$label+'/'+$x.Rel+': '+$_.Exception.Message);$script:failed=$true;Get-ChildItem -LiteralPath (Split-Path $path -Parent) -Filter '*.repair.*.tmp' -ErrorAction SilentlyContinue|Remove-Item -Force -ErrorAction SilentlyContinue}}
function FindBraveUntrapped{$out=@();$ud=Join-Path $env:LOCALAPPDATA 'BraveSoftware\Brave-Browser\User Data';if(-not(Test-Path -LiteralPath $ud)){return @()};$profiles=@(Get-ChildItem -LiteralPath $ud -Directory -ErrorAction SilentlyContinue|Where-Object{$_.Name -eq 'Default' -or $_.Name -like 'Profile *'});foreach($p in $profiles){$ed=Join-Path $p.FullName 'Extensions';if(-not(Test-Path -LiteralPath $ed)){continue};foreach($id in @(Get-ChildItem -LiteralPath $ed -Directory -ErrorAction SilentlyContinue)){foreach($v in @(Get-ChildItem -LiteralPath $id.FullName -Directory -ErrorAction SilentlyContinue)){ $m=Join-Path $v.FullName 'manifest.json';if(Test-Path -LiteralPath $m){try{if(([string](Get-Content -LiteralPath $m -Raw|ConvertFrom-Json).name)-eq 'Untrapped'){$out+=$v.FullName}}catch{}}}}};return @($out|Sort-Object -Unique)}
function RestartOwnedProcesses{Log 'RESTART Checking Untrapped-owned processes.';$stopped=$false;foreach($pat in @('*packet-filter.ps1*','*ultra-mode.ps1*')){@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.CommandLine -like $pat})|ForEach-Object{Log ('STOP PID '+$_.ProcessId+' '+$pat);Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue;$stopped=$true}};if($stopped){Start-Sleep -Milliseconds 800};foreach($f in @('packet-filter.ps1','ultra-mode.ps1')){$p=Join-Path $Root $f;if(Test-Path -LiteralPath $p){Log ('START '+$f);Start-Process powershell.exe -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$p) -WorkingDirectory $Root -Verb RunAs -WindowStyle Hidden -ErrorAction SilentlyContinue}};Log 'RESTART Complete.'}
$Core=@(@{Remote='ultra-mode/packet-filter.ps1';Rel='packet-filter.ps1';Type='script'},@{Remote='ultra-mode/ultra-mode.ps1';Rel='ultra-mode.ps1';Type='script'},@{Remote='ultra-mode/status-untrapped.ps1';Rel='status-untrapped.ps1';Type='script'},@{Remote='ultra-mode/self-repair.ps1';Rel='self-repair.ps1';Type='script'},@{Remote='ultra-mode/config.json';Rel='config.json';Type='json'})
$Ext=@(@{Remote='manifest.json';Rel='manifest.json';Type='json'},@{Remote='background.js';Rel='background.js';Type='js'},@{Remote='content.js';Rel='content.js';Type='js'},@{Remote='popup.html';Rel='popup.html';Type='text'},@{Remote='popup.js';Rel='popup.js';Type='js'},@{Remote='bootstrap.bundle.min.js';Rel='bootstrap.bundle.min.js';Type='js'})
try{Log '=== SELF-REPAIR BEGIN ===';[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12;Log 'Repair source: canonical GitHub main branch.';foreach($x in $Ext){RepairOne $ExtensionRoot $x 'extension-source'};foreach($x in $Core){RepairOne $Root $x 'ultra-mode'};Log 'BRAVE CHECK Searching installed profiles.';$matches=FindBraveUntrapped;Log ('BRAVE CHECK Installed Untrapped copies found: '+$matches.Count);foreach($m in $matches){foreach($x in $Ext){RepairOne $m $x 'brave-extension'}};foreach($native in @('WinDivert.dll','WinDivert64.sys')){if(Test-Path -LiteralPath (Join-Path $Root $native)){Log ('OK PRESENT '+$native)}else{Log ('FAIL MISSING '+$native);$script:failed=$true}};if($changed){RestartOwnedProcesses}else{Log 'RESTART NOT NEEDED No Untrapped-owned files changed.'};[void]$log.Add('');if($failed){[void]$log.Add('[DIAGNOSIS] REPAIR INCOMPLETE: one or more canonical components could not be repaired or verified.')}elseif($changed){[void]$log.Add('[DIAGNOSIS] REPAIR SUCCESS: canonical components were repaired and byte-for-byte verified.')}else{[void]$log.Add('[DIAGNOSIS] NO REPAIR REQUIRED: all repairable components matched canonical source.')};$log|Set-Content -LiteralPath $RepairReport -Encoding UTF8;Log '=== SELF-REPAIR END ===';if($changed -or $failed){Start-Process notepad.exe -ArgumentList $RepairReport -ErrorAction SilentlyContinue};if($failed){exit 1}else{exit 0}}catch{Log ('FATAL '+$_.Exception.Message);@('UNTRAPPED SELF-REPAIR FAILURE','Time: '+(Get-Date).ToString('yyyy-MM-dd HH:mm:ss zzz'),'[DIAGNOSIS] REPAIR ENGINE FAILURE: '+$_.Exception.Message)|Set-Content -LiteralPath $RepairReport -Encoding UTF8;Start-Process notepad.exe -ArgumentList $RepairReport -ErrorAction SilentlyContinue;exit 1}